import React, { useState, useRef, useEffect } from "react";
import music_off from '../assets/img/temp/music_off.png';
import music_on from '../assets/img/temp/music_on.png';
import favorites from '../assets/img/temp/favorites.png';
import gear_normal from '../assets/img/temp/gear_normal.png';
import myjp_icon from '../assets/img/temp/myjp_icon.png';
import jackpotSound from '../assets/sounds/myjackpot/intro.default.mp3';
import bgmusic from '../assets/sounds/common/bgmusic.mp3';

const IconMenu = () => {
    const [isMusicOn, setIsMusicOn] = useState(false);
    const audioRef = useRef(null);
    
    const playJackpotSound = () => {
        const audio = new Audio(jackpotSound);
        audio.play();
    }

    useEffect(() => {
        audioRef.current = new Audio(bgmusic);
        audioRef.current.loop = true;
        
        return () => {
            if (audioRef.current) {
                audioRef.current.pause();
                audioRef.current = null;
            }
        };
    }, []);

    useEffect(() => {
        if (audioRef.current) {
            if (isMusicOn) {
                audioRef.current.play().catch(error => {
                    console.error('Error playing audio:', error);
                });
            } else {
                audioRef.current.pause();
            }
        }
    }, [isMusicOn]);
    
    const toggleMusic = () => {
        setIsMusicOn(!isMusicOn);
    }

    return (
        <>
            <div className="flex mh-display-none md:hidden justify-between fixed bottom-[20%] px-[2px] w-full h-[8.48%]">
                <div className="w-[39.6%] flex justify-between">
                    <div className="w-[50%] h-full" onClick={toggleMusic} style={{ backgroundImage: `url(${isMusicOn ? music_on : music_off})`, backgroundSize: '100% 100%', backgroundPosition: 'center', backgroundRepeat: 'no-repeat' }}></div>
                    <div className="w-[50%] h-full scale-[1.4]" style={{ backgroundImage: `url(${myjp_icon})`, backgroundSize: '100% 100%', backgroundPosition: 'center', backgroundRepeat: 'no-repeat' }}></div>
                </div>

                <div className="w-[39.6%] flex justify-between">
                    <div className="w-[50%] h-full" style={{ backgroundImage: `url(${favorites})`, backgroundSize: '100% 100%', backgroundPosition: 'center', backgroundRepeat: 'no-repeat' }}></div>
                    <div className="w-[50%] h-full" style={{ backgroundImage: `url(${gear_normal})`, backgroundSize: '100% 100%', backgroundPosition: 'center', backgroundRepeat: 'no-repeat' }}></div>
                </div>
            </div>
            
            <div className="absolute hidden md:flex bottom-[20%] justify-between">
                <div className="flex flex-col">
                    <div className="w-[50%] h-full scale-[1.4]" style={{ backgroundImage: `url(${myjp_icon})`, backgroundSize: '100% 100%', backgroundPosition: 'center', backgroundRepeat: 'no-repeat' }}></div>
                    <div className="w-[50%] h-full" onClick={toggleMusic} style={{ backgroundImage: `url(${isMusicOn ? music_on : music_off})`, backgroundSize: '100% 100%', backgroundPosition: 'center', backgroundRepeat: 'no-repeat' }}></div>
                </div>
                
                <div className="flex flex-col">
                    <div className="w-[50%] h-full" style={{ backgroundImage: `url(${favorites})`, backgroundSize: '100% 100%', backgroundPosition: 'center', backgroundRepeat: 'no-repeat' }}></div>
                    <div className="w-[50%] h-full" style={{ backgroundImage: `url(${gear_normal})`, backgroundSize: '100% 100%', backgroundPosition: 'center', backgroundRepeat: 'no-repeat' }}></div>
                </div>
            </div>
        </>    
    );
};

export default IconMenu;